package com.kshitiz.taskforge.master.adapter.persistence;

import com.kshitiz.taskforge.master.domain.model.MasterItem;
import org.mapstruct.Mapper;

/**
 * Converts master-table rows into domain {@link MasterItem}s. The implementation is
 * generated by MapStruct at compile time (fields are matched by name).
 */
@Mapper
public interface MasterDataPersistenceMapper {

    /**
     * Converts one master-table row.
     *
     * @param entity row from any master table
     * @return the domain value
     */
    MasterItem toDomain(MasterDataJpaEntity entity);
}
